// ---------------- helpers ----------------
function runs(text, base = {}) {
  const out = [];
  for (const p of text.split(/(\*\*[^*]+\*\*|__[^_]+__)/g).filter((s) => s !== '')) {
    if (p.startsWith('**')) out.push(new TextRun({ text: p.slice(2, -2), bold: true, font: FONT, ...base }));
    else if (p.startsWith('__')) out.push(new TextRun({ text: p.slice(2, -2), italics: true, font: FONT, ...base }));
    else out.push(new TextRun({ text: p, font: FONT, ...base }));
  }
  return out;
}
const P = (t, o = {}) => new Paragraph({ spacing: { after: 120, line: 288 }, alignment: o.align || AlignmentType.JUSTIFIED, keepNext: o.keepNext, children: runs(t, o.run || {}) });
const H1 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun({ text: t, font: FONT })] });
const H2 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun({ text: t, font: FONT })] });
const B = (t) => new Paragraph({ numbering: { reference: 'bul', level: 0 }, spacing: { after: 60, line: 276 }, alignment: AlignmentType.JUSTIFIED, children: runs(t) });
const EQ = (t, n) => new Paragraph({ spacing: { before: 60, after: 100 }, alignment: AlignmentType.CENTER, tabStops: [{ type: 'right', position: W }],
  children: [new TextRun({ text: t, font: FONT }), new TextRun({ text: `\t(${n})`, font: FONT })] });
const PB = () => new Paragraph({ children: [new PageBreak()] });
const gap = () => new Paragraph({ spacing: { after: 80 }, children: [] });
const border = { style: BorderStyle.SINGLE, size: 4, color: 'BFC7D1' };
const borders = { top: border, bottom: border, left: border, right: border };
function cell(text, w, o = {}) {
  return new TableCell({ width: { size: w, type: WidthType.DXA }, borders,
    shading: o.fill ? { fill: o.fill, type: ShadingType.CLEAR, color: 'auto' } : undefined, margins: { top: 45, bottom: 45, left: 80, right: 80 },
    children: String(text).split('\n').map((line) => new Paragraph({ alignment: o.align, spacing: { after: 20 }, keepNext: o.keep, children: runs(line, { size: o.size || 17, bold: o.bold, color: o.color }) })) });
}
function table(headers, rows, widths, o = {}) {
  const sum = widths.reduce((a, b) => a + b, 0);
  return new Table({ width: { size: sum, type: WidthType.DXA }, columnWidths: widths, rows: [
    new TableRow({ tableHeader: true, children: headers.map((h, i) => cell(h, widths[i], { fill: BLUE, bold: true, color: 'FFFFFF', keep: true })) }),
    ...rows.map((r, ri) => new TableRow({ cantSplit: true, children: r.map((c, i) => cell(c, widths[i], { fill: ri % 2 ? 'F4F7FA' : undefined, bold: i === 0 && o.boldFirst, keep: rows.length <= 12 && ri < rows.length - 1 })) })),
  ] });
}
