const fmtSpec = (s) => { const k = s[0]; const g = (v) => (Math.abs(v) >= 1e4 || (Math.abs(v) < 1e-2 && v !== 0) ? v.toExponential(1) : String(+v.toPrecision(3))); return k === 'tri' ? `tri(${g(s[1])}, ${g(s[2])}, ${g(s[3])})` : k === 'uni' ? `uni(${g(s[1])}, ${g(s[2])})` : k === 'logn' ? `logn(${g(s[1])}, ${g(s[2])})` : `logu(${g(s[1])}, ${g(s[2])})`; };
const prow = (k, s) => [PR.lab[k] || k, k, fmtSpec(s), PR.units[k] || '\u2013'];
c.push(table(['Parameter', 'Key', 'Distribution', 'Unit'], Object.entries(PR.common).map(([k, s]) => prow(k, s)), [3000, 1300, 3560, 1500]));
c.push(gap());
